class T{String s(boolean P,String[]g){var G=String.join("",g);int C=g[0].length(),N=G.length(),S=G.indexOf(83),E=G.indexOf(69),m=P?2:20;int[]q=new int[N],v=new int[N],D={1,-1,C,-C};int h=0,t=1;q[0]=S;v[S]=S+1;while(v[E]<1){int p=q[h++];for(int x:D){int j=p+x;if(j>=0&j<N&&Math.abs(j%C-p%C)<2&G.charAt(j)>35&v[j]<1){v[j]=p+1;q[t++]=j;}}}t=0;for(int i=E;i!=S;i=v[i]-1)q[t++]=i;q[t++]=S;long A=0;for(int i=0;i<t;i++)for(int j=i+100;j<t;j++){int z=Math.abs(q[i]/C-q[j]/C)+Math.abs(q[i]%C-q[j]%C);if(z<=m&j-i-z>=100)A++;}return""+A;}}
